if(a==='catalog-apply-one'){const legacyId=Number(b.dataset.legacyId||0);if(!legacyId||!await adminConfirm('این محصول قدیمی به کاتالوگ جدید نگاشت شود؟ چیزی حذف نمی‌شود.',{title:'انتقال به کاتالوگ جدید',confirmText:'انتقال',danger:false}))return;return call('admin_catalog_apply_one',{legacy_product_id:legacyId,confirm:'APPLY'},'محصول به کاتالوگ جدید منتقل شد.')}
