if(a==='catalog-wizard-mode'){catalogCollectWizard();catalogWizardState.mode=b.dataset.mode==='direct'?'direct':'grouped';if(catalogWizardState.mode==='direct'&&!catalogWizardState.groups.some(g=>g.is_default))catalogWizardState.groups.unshift(catalogNormalizeGroup({is_default:1,name:'Default Group'}));if(catalogWizardState.mode==='grouped'&&!catalogWizardState.groups.some(g=>!g.is_default))catalogWizardState.groups.push(catalogNormalizeGroup({name:'Standard'}));catalogSaveDraft();return renderCatalogWizard()}
