if(a==='catalog-wizard-remove-plan'){catalogCollectWizard();const g=catalogWizardState.groups.find(x=>x.key===b.dataset.groupKey),p=g?.plans.find(x=>x.key===b.dataset.key);if(p?.id&&!await adminConfirm(`پلن «${p.title}» غیرفعال شود؟ سفارش‌های قبلی دست‌نخورده می‌مانند.`,{title:'غیرفعال‌سازی پلن'}))return;if(g){g.plans=g.plans.filter(x=>x.key!==b.dataset.key);catalogSaveDraft();return renderCatalogWizard()}return}
