if(a==='add-inventory')return modal('افزودن انبار',inventoryForm(),{wide:true});if(a==='edit-inventory'){const i=(S.inventory||[]).find(x=>Number(x.id)===id);return modal('ویرایش انبار',inventoryForm(i||{}),{wide:true})}if(a==='soft-delete-inventory'){if(await adminConfirm('آیتم موجود حذف امن شود؟',{title:'حذف امن موجودی'}))return call('admin_delete_inventory',{inventory_id:id})}if(a==='hard-delete-inventory'){if(await adminConfirm('آیتم کامل حذف شود؟',{title:'حذف کامل موجودی',confirmText:'حذف کامل'}))return call('admin_hard_delete_inventory',{inventory_id:id})}
if(a==='add-coupon')return modal('کد تخفیف جدید',couponForm(),{wide:true});if(a==='edit-coupon'){const c=(S.coupons||[]).find(x=>Number(x.id)===id);return modal('ویرایش کد تخفیف',couponForm(c||{}),{wide:true})}if(a==='toggle-coupon')return call('admin_toggle_coupon',{coupon_id:id});if(a==='delete-coupon'){if(await adminConfirm('کد تخفیف حذف شود؟',{title:'حذف کد تخفیف'}))return call('admin_delete_coupon',{coupon_id:id})}
